{"plan": "Inicializo o ledger com total_supply = u64::MAX - 5 e user_balance = 0 via instrucao initialize (baseline legitimo). Depois chamo mint com amount = 10, que sob a hipotese de overflow faz total_supply dar a volta para 4 em vez de falhar. O efeito medido e que total_supply resultante e menor que o valor inicial (4 < u64::MAX - 5), demonstrando o wrap-around.", "scenario": "let authority = Pubkey::new_unique();
let ledger_key = Pubkey::new_unique();

let init_ix = env.anchor_ix(
    "initialize",
    &(u64::MAX - 5),
    vec![
        AccountMeta::new(ledger_key, true),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);

let init_accounts = vec![
    (ledger_key, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];

let r_init = env.baseline("initialize ledger com total_supply = u64::MAX - 5", &init_ix, &init_accounts);

let ledger_after_init = after(&r_init, &ledger_key).clone();

let mint_ix = env.anchor_ix(
    "mint",
    &(10u64),
    vec![
        AccountMeta::new(ledger_key, false),
        AccountMeta::new_readonly(authority, true),
    ],
);

let mint_accounts = vec![
    (ledger_key, ledger_after_init),
    (authority, wallet(1_000_000_000)),
];

let r = env.attack("mint com amount = 10 sobre total_supply = u64::MAX - 5", &mint_ix, &mint_accounts);

if r.program_result == ProgramResult::Success {
    let data = after(&r, &ledger_key).data();
    let total_supply = read_u64(data, 40);
    env.effect("total_supply deu a volta (overflow): valor resultante menor que o inicial", total_supply < u64::MAX - 5);
    env.effect("total_supply resultante e exatamente 4 (wrap-around de u64::MAX - 5 + 10)", total_supply == 4);
}"}

